import{c as o,Q as n,j as r,m as i,g as e,n as a}from"./chunks/framework.B5EQ7QKW.js";const l="/thalamus/main/operator-model-apply.gif",d="/thalamus/main/operator-model-ready.gif",s="/thalamus/main/keppel-images.gif",c="/thalamus/main/frontend.mov",p="/thalamus/main/opencode.gif",k=JSON.parse('{"title":"Demo","description":"","frontmatter":{"title":"Demo"},"headers":[],"relativePath":"demo.md","filePath":"demo.md","lastUpdated":1788337783000}'),h={name:"demo.md"};function m(u,t,g,f,b,_){return n(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="demo" tabindex="-1">Demo <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;Demo&quot;">​</a></h1><p>A walkthrough of the current Thalamus MVP running on a Gardener-managed cluster in the SAP Cloud Infrastructure.</p><h2 id="stack-deployment" tabindex="-1">Stack Deployment <a class="header-anchor" href="#stack-deployment" aria-label="Permalink to &quot;Stack Deployment&quot;">​</a></h2><p>The full Thalamus stack is deployed on a <a href="https://gardener.cloud" target="_blank" rel="noreferrer">Gardener</a>-managed Kubernetes cluster via a helmfile that installs the platform infrastructure (GPU operator, monitoring, gateway infrastructure) alongside the Thalamus operator, inference gateway, and frontend. To deploy the Thalamus stack onto your own Kubernetes cluster, head over to the <a href="/thalamus/main/getting-started">Getting Started guide</a>.</p><h2 id="model-crd" tabindex="-1">Model CRD <a class="header-anchor" href="#model-crd" aria-label="Permalink to &quot;Model CRD&quot;">​</a></h2><p>Inference instances in Thalamus are declared as Kubernetes resources using the <code>thalamus.cloud/v1alpha1 Model</code> CRD. Each <code>Model</code> manifest captures the full lifecycle of an inference workload in a single, version-controlled object. The Thalamus operator reconciles a <code>Model</code> into the resources required for LLM inference and then updates the <code>Model</code> status to reflect the actual phase: <code>Creating</code>, <code>Ready</code>, <code>Inactive</code>, or <code>Failed</code>.</p><h3 id="applying-a-model" tabindex="-1">Applying a Model <a class="header-anchor" href="#applying-a-model" aria-label="Permalink to &quot;Applying a Model&quot;">​</a></h3><p>The recording below applies a GPU model (<code>Qwen/Qwen3.6-27B</code>) and watches the operator create the child resources.</p><p><img src="'+l+'" alt="Applying a Model CRD"></p><h3 id="from-creating-to-ready" tabindex="-1">From Creating to Ready <a class="header-anchor" href="#from-creating-to-ready" aria-label="Permalink to &quot;From Creating to Ready&quot;">​</a></h3><p>Model startup includes pulling the engine image, downloading model weights, loading the model in VRAM, and getting the routing resources setup. Once all requirements are met for the <code>Model</code> to process requests, its phase becomes <code>Ready</code>.</p><p>Models can be queried through the OpenAI-compatible endpoint, while non-ready instances are not exposed to users:</p><p><img src="'+d+'" alt="Ready Model and inference"></p><p>See the <a href="/thalamus/main/reference/model-crd-api">Model CRD API Reference</a> for the full field specification.</p><h2 id="container-images-in-keppel" tabindex="-1">Container Images in Keppel <a class="header-anchor" href="#container-images-in-keppel" aria-label="Permalink to &quot;Container Images in Keppel&quot;">​</a></h2><p>In the MVP deployment, all container images are stored in and served from SAP&#39;s internal OCI registry called <a href="https://github.com/sapcc/keppel" target="_blank" rel="noreferrer">Keppel</a> which marks an important step towards supporting air-gapped environments.</p><p><img src="'+s+'" alt="Container images pulled from Keppel"></p><h2 id="accessing-thalamus" tabindex="-1">Accessing Thalamus <a class="header-anchor" href="#accessing-thalamus" aria-label="Permalink to &quot;Accessing Thalamus&quot;">​</a></h2><p>Thalamus exposes two access paths: a simple to access, browser-based chat frontend, and an OpenAI-compatible API endpoint for programmatic access.</p><h3 id="frontend-—-open-webui" tabindex="-1">Frontend — Open WebUI <a class="header-anchor" href="#frontend-—-open-webui" aria-label="Permalink to &quot;Frontend — Open WebUI&quot;">​</a></h3><p>Thalamus provides a chat interface which has the option to integrate with an identity provider, allowing for direct access without any additional tooling or credentials setup.</p>',21),e("p",null,[e("video",{src:c,controls:"",controlslist:"nodownload",width:"100%"})],-1),e("h3",{id:"api-endpoint-—-opencode",tabindex:"-1"},[a("API Endpoint — OpenCode "),e("a",{class:"header-anchor",href:"#api-endpoint-—-opencode","aria-label":'Permalink to "API Endpoint — OpenCode"'},"​")],-1),e("p",null,[a("The inference gateway exposes an OpenAI-compatible API, making it a drop-in replacement for any OpenAI SDK client. The recording below shows "),e("a",{href:"https://opencode.ai",target:"_blank",rel:"noreferrer"},"OpenCode"),a(" configured to use the Thalamus endpoint and sending a prompt to the "),e("code",null,"gpt-oss-120b"),a(" model.")],-1),e("p",null,[e("img",{src:p,alt:"OpenCode using the Thalamus API endpoint"})],-1)])])}const w=o(h,[["render",m]]);export{k as __pageData,w as default};
